def check_solution(x, y, z):
    """Checks if the triple (x, y, z) satisfies the equation."""
    return x**3 + y**3 + z**3 == x**2 * y**2 * z**2

solutions = []
max_val = 10

# Search over x, y, z such that 1 <= x <= y <= z <= max_val
for x in range(1, max_val + 1):
    for y in range(x, max_val + 1):
        for z in range(y, max_val + 1):
            if check_solution(x, y, z):
                solutions.append((x, y, z))

print("Found solutions:")
if solutions:
    for sol in solutions:
        print(sol)
else:
    print("No solutions found in the current search range.")
